//! Configuration module for Link.Assistant.Router.
//!
//! Loads configuration from CLI arguments, environment variables, and `.lenv`
//! files via `lino-arguments` (a `clap` drop-in). The struct returned here is
//! the canonical runtime config used by the rest of the crate.

// `Config` and `BuildArgs` carry one bool per documented feature toggle
// (`enable_openai_api`, `enable_anthropic_api`, ...). Collapsing them into
// enums would diverge from the CLI/env variable names that ship as public API.

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum UpstreamProvider {
    /// Automatically route requests across every healthy vendor subscription.
    #[default]
    Auto,
    /// Anthropic via Claude MAX OAuth credentials.
    Anthropic,
    /// Gonka OpenAI-compatible inference provider.
    Gonka,
    /// Crater `ForgeFed` task provider.
    Crater,
    /// `OpenAI` Codex / `ChatGPT` subscription via `~/.codex` OAuth credentials.
    Codex,
    /// Google Gemini Code Assist subscription via `~/.gemini` OAuth credentials.
    Gemini,
    /// Alibaba Qwen subscription via `~/.qwen` OAuth credentials (`DashScope`).
    Qwen,
    /// Generic OpenAI-compatible inference provider, including `LiteLLM` proxy.
    OpenAICompatible,
    /// Policy-gated personal z.ai GLM Coding Plan credential.
    ZaiCodingPlan,
}

impl UpstreamProvider {
    /// Parse a provider from a free-form string.
    #[must_use]
    pub fn from_str_opt(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "auto" | "all" => Some(Self::Auto),
            "anthropic" | "claude" => Some(Self::Anthropic),
            "gonka" => Some(Self::Gonka),
            "crater" | "forgefed" => Some(Self::Crater),
            "codex" | "chatgpt" | "openai-codex" => Some(Self::Codex),
            "gemini" | "google" | "code-assist" => Some(Self::Gemini),
            "qwen" | "qwen-code" | "dashscope" => Some(Self::Qwen),
            "openai" | "openai-compatible" | "openai_like" | "litellm" => {
                Some(Self::OpenAICompatible)
            }
            "z.ai-coding-plan" | "zai-coding-plan" => Some(Self::ZaiCodingPlan),
            _ => None,
        }
    }

    /// The subscription provider backing this upstream, when it is one of the
    /// vendor-subscription providers (Claude/Codex/Gemini/Qwen).
    #[must_use]
    pub const fn subscription_provider(self) -> Option<crate::subscription::SubscriptionProvider> {
        use crate::subscription::SubscriptionProvider as S;
        match self {
            Self::Anthropic => Some(S::Claude),
            Self::Codex => Some(S::Codex),
            Self::Gemini => Some(S::Gemini),
            Self::Qwen => Some(S::Qwen),
            Self::Auto
            | Self::Gonka
            | Self::Crater
            | Self::OpenAICompatible
            | Self::ZaiCodingPlan => None,
        }
    }

    /// Canonical lowercase name, used in logs, metrics, and audit records.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Auto => "auto",
            Self::Anthropic => "anthropic",
            Self::Gonka => "gonka",
            Self::Crater => "crater",
            Self::Codex => "codex",
            Self::Gemini => "gemini",
            Self::Qwen => "qwen",
            Self::OpenAICompatible => "openai-compatible",
            Self::ZaiCodingPlan => "z.ai-coding-plan",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ApiFormat {
    /// Anthropic Messages API (`/v1/messages`).
    Anthropic,
    /// Amazon Bedrock `InvokeModel` API (`/invoke`).
    Bedrock,
    /// Google Vertex AI rawPredict API (`:rawPredict`).
    Vertex,
}

impl ApiFormat {
    /// Parse a format from a free-form string.
    #[must_use]
    pub fn from_str_opt(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "anthropic" | "messages" => Some(Self::Anthropic),
            "bedrock" | "invoke" => Some(Self::Bedrock),
            "vertex" | "rawpredict" => Some(Self::Vertex),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum RoutingMode {
    /// Forward HTTP requests directly to Anthropic / Bedrock / Vertex.
    #[default]
    Direct,
    /// Drive a local Claude Code CLI subprocess for tool-heavy compatibility.
    Cli,
    /// Try `Direct` first and fall back to `Cli` for routes that need it.
    Hybrid,
}

impl RoutingMode {
    /// Parse a mode from a free-form string.
    #[must_use]
    pub fn from_str_opt(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "direct" => Some(Self::Direct),
            "cli" | "subprocess" => Some(Self::Cli),
            "hybrid" | "auto" => Some(Self::Hybrid),
            _ => None,
        }
    }
}

impl FromStr for RoutingMode {
    type Err = ConfigError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        Self::from_str_opt(s).ok_or(ConfigError::InvalidRoutingMode)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum StoragePolicy {
    /// Use only the in-memory store (no persistence; tests / ephemeral runs).
    Memory,
    /// Persist to a Lino-encoded text file.
    Text,
    /// Persist to a binary file (length-prefixed records, link-cli compatible
    /// when the `clink` adapter is enabled).
    Binary,
    /// Dual-write to both text and binary (default per issue #7).
    #[default]
    Both,
}

impl StoragePolicy {
    /// Parse a policy from a free-form string.
    #[must_use]
    pub fn from_str_opt(s: &str) -> Option<Self> {
        match s.to_lowercase().as_str() {
            "memory" | "mem" | "none" => Some(Self::Memory),
            "text" | "lino" => Some(Self::Text),
            "binary" | "bin" | "link-cli" | "linkcli" | "clink" => Some(Self::Binary),
            "both" | "dual" => Some(Self::Both),
            _ => None,
        }
    }
}

#[derive(Clone)]
pub struct Config {
    /// Address and port to bind the server to.
    pub listen_addr: SocketAddr,
    /// Secret used for signing and validating custom tokens.
    pub token_secret: String,
    /// Path to the Claude Code home directory containing session credentials.
    pub claude_code_home: String,
    /// Upstream Anthropic API base URL.
    pub upstream_base_url: String,
    /// Whether verbose logging is enabled.
    pub verbose: bool,
    /// Maximum request body accepted by raw proxy surfaces.
    pub max_proxy_request_bytes: usize,
    /// Optional explicit upstream API format restriction.
    pub api_format: Option<ApiFormat>,
    /// Routing mode (direct / cli / hybrid).
    pub routing_mode: RoutingMode,
    /// Token persistence policy.
    pub storage_policy: StoragePolicy,
    /// Directory where token state files live.
    pub data_dir: PathBuf,
    /// User home from which vendor credential roots are derived.
    pub client_home: PathBuf,
    /// Whether `client_home` came from the explicit isolation boundary.
    pub isolated_client_home: bool,
    /// Optional path to the local `claude` CLI binary used by the CLI backend.
    pub claude_cli_bin: Option<PathBuf>,
    /// Optional path to the local `codex` CLI binary used by credential
    /// recovery (issue #275).
    pub codex_cli_bin: Option<PathBuf>,
    /// Selected upstream inference provider.
    pub upstream_provider: UpstreamProvider,
    /// Gonka broker/API-key credential. Never log this.
    pub gonka_api_key: Option<String>,
    /// Explicit Gonka broker URL. Direct-wallet node endpoints are not defaults.
    pub gonka_source_url: Option<String>,
    /// Default Gonka model used when requests omit `model`.
    pub gonka_model: String,
    /// Upstream model used when an Anthropic-dialect request is bridged to a
    /// non-Anthropic upstream. `None` selects one from the live catalog.
    pub bridge_model: Option<String>,
    /// How a bridge model is chosen from the live catalog.
    pub bridge_model_policy: crate::bridge_selection::BridgeModelPolicy,
    /// Path of the append-only per-token audit log. `None` disables auditing.
    pub audit_log: Option<String>,
    /// Crater `ForgeFed` task provider configuration.
    pub crater: crate::crater::CraterConfig,
    /// Generic OpenAI-compatible provider config for `LiteLLM` and similar
    /// gateways.
    pub openai_compatible: crate::providers::OpenAICompatibleConfig,
    /// Public base URL used for `ActivityPub` actor and collection IDs.
    pub activitypub_actor_base_url: String,
    /// Public key PEM advertised on the `ActivityPub` actor.
    pub activitypub_public_key_pem: String,
    /// Whether to enable the OpenAI-compatible API surface.
    pub enable_openai_api: bool,
    /// Whether to enable the Anthropic-compatible (direct) proxy surface.
    pub enable_anthropic_api: bool,
    /// Whether to expose `/metrics` and other operational endpoints.
    pub enable_metrics: bool,
    /// Serve only neutral health and AI inference/catalog routes on the main
    /// listener. Management and private integration services remain absent.
    pub inference_only: bool,
    /// Explicit primary listeners, each with its own route set and transport.
    /// Empty preserves the historical single-listener behavior.
    pub listeners: Vec<crate::primary_listener::PrimaryListenerConfig>,
    /// Optional comma-separated list of additional credential directories for
    /// the active vendor-subscription provider.
    pub additional_account_dirs: Vec<PathBuf>,
    /// Selection policy applied to new sessions in a multi-account pool.
    pub account_routing_strategy: SelectionStrategy,
    /// Default cooldown after an account returns a typed quota failure.
    pub account_cooldown_secs: u64,
    /// Inactive session-affinity lifetime. Zero disables affinity.
    pub session_affinity_ttl_secs: u64,
    /// Per-account request caps, ordered primary then additional. Zero means
    /// unknown/unlimited.
    pub account_request_limits: Vec<usize>,
    /// Whether to enable experimental compatibility features (spoofing,
    /// XML history reconstruction, etc.). Off by default.
    pub experimental_compatibility: bool,
    /// Exact, audited client/provider consumer-subscription bridge cells.
    pub subscription_entitlement_policy: crate::client_policy::SubscriptionEntitlementPolicy,
    /// Optional flat bootstrap admin key accepted by the admin endpoints in
    /// addition to admin-scoped `la_sk_…` tokens.
    pub admin_key: Option<String>,
    /// Explicit opt-out that leaves the admin endpoints open to
    /// unauthenticated callers. Off by default: a deployment with no admin
    /// credential configured mints a bootstrap one at startup instead.
    pub allow_anonymous_admin: bool,
    /// Explicit, bounded emergency any-token mode (issue #645). Off unless
    /// `--emergency-accept-any-token` is given.
    pub emergency_auth: crate::emergency_auth::EmergencyAuthConfig,
    /// Account-pool failover, threshold pause and warmup interception
    /// (issues #676, #677). Defaults keep the historical behaviour.
    pub pool: crate::pool_failover::PoolPolicy,
    /// Optional MPP charge settings for OpenAI-compatible endpoints.
    pub mpp: crate::mpp::MppConfig,
    /// Interactive login API settings (`/api/management/login`).
    pub login: crate::login::LoginConfig,
    /// Opt-in admin UI listener (separate port, disabled by default).
    pub admin_ui: crate::admin::AdminUiConfig,
    /// Management listener policy and failed-authentication lockout.
    pub management: crate::management_config::ManagementConfig,
    /// Optional operator definitions over authenticated live model catalogs.
    pub model_catalog_sources: crate::model_catalog_sources::CatalogSourcesConfig,
    /// Opt-in Telegram/VK admin channels (disabled unless a bot token is set).
    pub chat_admin: crate::chat_admin::ChatAdminConfig,
}

impl std::fmt::Debug for Config {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter
            .debug_struct("Config")
            .field("listen_addr", &self.listen_addr)
            .field("upstream_provider", &self.upstream_provider)
            .field(
                "gonka_api_key",
                &self.gonka_api_key.as_ref().map(|_| "[REDACTED]"),
            )
            .field("gonka_source_url", &self.gonka_source_url)
            .field("gonka_model", &self.gonka_model)
            .field("data_dir", &self.data_dir)
            .finish_non_exhaustive()
    }
}

impl Config {
    /// The vendor subscription this deployment serves and the credential home
    /// its primary account reads from.
    ///
    /// Both the server and the CLI subcommands need the same answer, and it is
    /// derived purely from configuration.
    #[must_use]
    pub fn subscription_pool(&self) -> (SubscriptionProvider, PathBuf) {
        let provider = self
            .upstream_provider
            .subscription_provider()
            .unwrap_or(SubscriptionProvider::Claude);
        let primary = self.credential_home(provider);
        (provider, primary)
    }

    /// Exact credential home used for one vendor by every local command.
    #[must_use]
    pub fn credential_home(&self, provider: SubscriptionProvider) -> PathBuf {
        match provider {
            SubscriptionProvider::Claude => PathBuf::from(&self.claude_code_home),
            SubscriptionProvider::Codex => self.login.codex_home.clone(),
            SubscriptionProvider::Gemini | SubscriptionProvider::Qwen => {
                if self.isolated_client_home {
                    self.client_home.join(provider.home_subdir())
                } else {
                    provider.resolve_home(&self.client_home.to_string_lossy())
                }
            }
        }
    }

    /// Readers rooted at the exact homes selected during CLI parsing.
    #[must_use]
    pub fn subscription_readers(&self) -> Vec<crate::subscription::SubscriptionReader> {
        SubscriptionProvider::ALL
            .into_iter()
            .map(|provider| {
                crate::subscription::SubscriptionReader::new(
                    provider,
                    self.credential_home(provider),
                )
            })
            .collect()
    }

    /// Load configuration from environment variables only (legacy compatibility).
    ///
    /// The binary's CLI entrypoint layers command-line flags and `.lenv`
    /// overrides onto this environment configuration.
    pub fn from_env() -> Result<Self, ConfigError> {
        let port =
            crate::operation_context::var("ROUTER_PORT").unwrap_or_else(|_| "8080".to_string());
        let host =
            crate::operation_context::var("ROUTER_HOST").unwrap_or_else(|_| "0.0.0.0".to_string());
        let token_secret =
            crate::token_secret::or_from_file(crate::operation_context::var("TOKEN_SECRET").ok())
                .map_err(ConfigError::TokenSecretFile)?;
        let claude_code_home =
            crate::operation_context::var("CLAUDE_CODE_HOME").unwrap_or_else(|_| {
                let home =
                    crate::operation_context::var("HOME").unwrap_or_else(|_| "/root".to_string());
                format!("{home}/.claude")
            });
        let codex_home = SubscriptionProvider::Codex.resolve_home(
            &crate::operation_context::var("HOME").unwrap_or_else(|_| "/root".to_string()),
        );
        let upstream_base_url = crate::operation_context::var("UPSTREAM_BASE_URL")
            .unwrap_or_else(|_| "https://api.anthropic.com".to_string());
        let verbose = crate::operation_context::var("VERBOSE")
            .is_ok_and(|v| v == "1" || v.eq_ignore_ascii_case("true"));
        let max_proxy_request_bytes = crate::operation_context::var("MAX_PROXY_REQUEST_BYTES")
            .ok()
            .and_then(|value| value.parse().ok())
            .unwrap_or(DEFAULT_MAX_PROXY_REQUEST_BYTES);
        let api_format = crate::operation_context::var("UPSTREAM_API_FORMAT")
            .ok()
            .and_then(|s| ApiFormat::from_str_opt(&s));
        let routing_mode = crate::operation_context::var("ROUTING_MODE")
            .ok()
            .and_then(|s| RoutingMode::from_str_opt(&s))
            .unwrap_or_default();
        let storage_policy = crate::operation_context::var("STORAGE_POLICY")
            .ok()
            .and_then(|s| StoragePolicy::from_str_opt(&s))
            .unwrap_or_default();
        let data_dir = crate::operation_context::var("DATA_DIR")
            .map_or_else(|_| default_data_dir(), PathBuf::from);
        let claude_cli_bin = crate::operation_context::var("CLAUDE_CLI_BIN")
            .ok()
            .map(PathBuf::from);
        let codex_cli_bin = crate::operation_context::var("CODEX_CLI_BIN")
            .ok()
            .map(PathBuf::from);
        let upstream_provider = crate::operation_context::var("UPSTREAM_PROVIDER")
            .ok()
            .and_then(|s| UpstreamProvider::from_str_opt(&s))
            .unwrap_or_default();
        let gonka_private_key = crate::operation_context::var("GONKA_PRIVATE_KEY")
            .ok()
            .filter(|s| !s.is_empty());
        let gonka_api_key = crate::operation_context::var("GONKA_API_KEY")
            .ok()
            .filter(|s| !s.is_empty());
        let gonka_source_url = crate::operation_context::var("GONKA_SOURCE_URL")
            .ok()
            .filter(|s| !s.is_empty());
        let gonka_model =
            crate::operation_context::var("GONKA_MODEL").unwrap_or_else(|_| default_gonka_model());
        let bridge_model = crate::operation_context::var("ANTHROPIC_BRIDGE_MODEL")
            .ok()
            .filter(|s| !s.is_empty());
        let bridge_model_policy = crate::operation_context::var("BRIDGE_MODEL_POLICY")
            .ok()
            .filter(|s| !s.is_empty());
        let audit_log = crate::operation_context::var("AUDIT_LOG")
            .ok()
            .filter(|s| !s.is_empty());
        let activitypub_actor_base_url =
            crate::operation_context::var("ACTIVITYPUB_ACTOR_BASE_URL")
                .unwrap_or_else(|_| format!("http://{host}:{port}"));
        let crater_actor = crate::operation_context::var("CRATER_FORGEFED_ACTOR")
            .ok()
            .filter(|s| !s.is_empty())
            .unwrap_or_else(|| {
                format!(
                    "{}/api/services/activitypub/actor/code",
                    activitypub_actor_base_url.trim_end_matches('/')
                )
            });
        let crater = crate::crater::CraterConfig::new(
            crate::operation_context::var("CRATER_FORGEFED_INBOX")
                .ok()
                .filter(|s| !s.is_empty()),
            &crater_actor,
            crate::operation_context::var("CRATER_FORGEFED_TARGET")
                .ok()
                .filter(|s| !s.is_empty()),
            Duration::from_millis(parse_u64_env("CRATER_POLL_INTERVAL_MS", 1000)),
            Duration::from_secs(parse_u64_env("CRATER_POLL_TIMEOUT_SECS", 120)),
        );
        let openai_compatible = crate::providers::OpenAICompatibleConfig {
            provider_name: crate::operation_context::var("OPENAI_COMPATIBLE_PROVIDER_NAME")
                .unwrap_or_else(|_| "litellm".to_string()),
            base_url: crate::operation_context::var("OPENAI_COMPATIBLE_BASE_URL")
                .unwrap_or_else(|_| default_openai_compatible_base_url()),
            api_key: crate::operation_context::var("OPENAI_COMPATIBLE_API_KEY")
                .ok()
                .filter(|s| !s.is_empty()),
            api_key_env: crate::operation_context::var("OPENAI_COMPATIBLE_API_KEY_ENV")
                .ok()
                .filter(|s| !s.is_empty()),
            default_model: crate::operation_context::var("OPENAI_COMPATIBLE_MODEL")
                .ok()
                .filter(|s| !s.is_empty()),
            models: crate::operation_context::var("OPENAI_COMPATIBLE_MODELS")
                .ok()
                .map(|raw| parse_csv(&raw))
                .unwrap_or_default(),
            supported_clients: crate::operation_context::var("OPENAI_COMPATIBLE_SUPPORTED_CLIENTS")
                .ok()
                .map(|raw| parse_csv(&raw))
                .unwrap_or_default(),
        };
        let activitypub_public_key_pem =
            crate::operation_context::var("ACTIVITYPUB_PUBLIC_KEY_PEM")
                .unwrap_or_else(|_| default_activitypub_public_key_pem());
        let enable_openai_api = crate::operation_context::var("ENABLE_OPENAI_API")
            .map_or(true, |v| {
                !matches!(v.as_str(), "0" | "false" | "FALSE" | "off")
            });
        let enable_anthropic_api = crate::operation_context::var("ENABLE_ANTHROPIC_API")
            .map_or(true, |v| {
                !matches!(v.as_str(), "0" | "false" | "FALSE" | "off")
            });
        let enable_metrics = crate::operation_context::var("ENABLE_METRICS").map_or(true, |v| {
            !matches!(v.as_str(), "0" | "false" | "FALSE" | "off")
        });
        let inference_only = crate::operation_context::var("INFERENCE_ONLY")
            .is_ok_and(|v| matches!(v.as_str(), "1" | "true" | "TRUE" | "on" | "ON"));
        let listeners = crate::operation_context::var("LISTENERS")
            .ok()
            .map(|raw| {
                raw.split(';')
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .map(str::to_string)
                    .collect()
            })
            .unwrap_or_default();
        let additional_account_dirs = crate::operation_context::var("ADDITIONAL_ACCOUNT_DIRS")
            .ok()
            .map(|raw| {
                raw.split(',')
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                    .map(PathBuf::from)
                    .collect()
            })
            .unwrap_or_default();
        let account_routing_strategy =
            match crate::operation_context::var("ACCOUNT_ROUTING_STRATEGY") {
                Ok(value) => SelectionStrategy::from_str_opt(&value)
                    .ok_or(ConfigError::InvalidAccountRoutingStrategy)?,
                Err(_) => SelectionStrategy::default(),
            };
        let account_cooldown_secs = parse_u64_env("ACCOUNT_COOLDOWN_SECS", 60);
        let session_affinity_ttl_secs = parse_u64_env("SESSION_AFFINITY_TTL_SECS", 3600);
        let account_request_limits = crate::operation_context::var("ACCOUNT_REQUEST_LIMITS")
            .ok()
            .map(|raw| parse_usize_csv(&raw))
            .transpose()?
            .unwrap_or_default();
        let experimental_compatibility =
            crate::operation_context::var("EXPERIMENTAL_COMPATIBILITY")
                .is_ok_and(|v| v == "1" || v.eq_ignore_ascii_case("true"));
        let subscription_bridge_overrides =
            crate::operation_context::var("SUBSCRIPTION_BRIDGE_OVERRIDES")
                .ok()
                .map(|raw| parse_csv(&raw))
                .unwrap_or_default();
        let proxied_client_overrides = crate::operation_context::var("PROXIED_CLIENT_OVERRIDES")
            .ok()
            .map(|raw| parse_csv(&raw))
            .unwrap_or_default();
        let admin_key = crate::operation_context::var("TOKEN_ADMIN_KEY")
            .ok()
            .filter(|s| !s.is_empty());
        let allow_anonymous_admin = crate::operation_context::var("ALLOW_ANONYMOUS_ADMIN")
            .is_ok_and(|v| v == "1" || v.eq_ignore_ascii_case("true"));
        let login = crate::login::LoginConfig {
            enabled: crate::operation_context::var("ENABLE_LOGIN_API").map_or(true, |v| {
                !matches!(v.as_str(), "0" | "false" | "FALSE" | "off")
            }),
            command: crate::operation_context::var("LOGIN_CLI_COMMAND")
                .unwrap_or_else(|_| "claude".to_string()),
            args: crate::operation_context::var("LOGIN_CLI_ARGS")
                .ok()
                .filter(|raw| !raw.trim().is_empty())
                .map_or_else(Vec::new, |raw| parse_csv(&raw)),
            session_ttl: Duration::from_secs(parse_u64_env("LOGIN_SESSION_TTL_SECS", 900)),
            max_sessions: usize::try_from(parse_u64_env("LOGIN_MAX_SESSIONS", 4)).unwrap_or(4),
            codex_home,
            ..crate::login::LoginConfig::default()
        };
        let mpp = crate::mpp::MppConfig {
            enabled: crate::operation_context::var("MPP_ENABLE")
                .is_ok_and(|v| matches!(v.as_str(), "1" | "true" | "TRUE" | "on" | "ON")),
            amount: crate::operation_context::var("MPP_AMOUNT")
                .unwrap_or_else(|_| "0.00".to_string()),
            currency: crate::operation_context::var("MPP_CURRENCY")
                .unwrap_or_else(|_| "USD".to_string()),
            recipient: crate::operation_context::var("MPP_RECIPIENT").unwrap_or_default(),
            method: crate::operation_context::var("MPP_METHOD")
                .ok()
                .filter(|s| !s.is_empty()),
        };

        let admin_ui = admin_ui_from_env()?;
        let chat_admin = chat_admin_from_env()?;

        Self::build(BuildArgs {
            host: &host,
            port: &port,
            token_secret: token_secret.as_deref(),
            claude_code_home: &claude_code_home,
            upstream_base_url: &upstream_base_url,
            verbose,
            max_proxy_request_bytes,
            api_format,
            routing_mode,
            storage_policy,
            data_dir,
            claude_cli_bin,
            codex_cli_bin,
            upstream_provider,
            gonka_private_key,
            gonka_api_key,
            gonka_source_url,
            gonka_model,
            bridge_model,
            bridge_model_policy,
            audit_log,
            crater,
            openai_compatible,
            activitypub_actor_base_url,
            activitypub_public_key_pem,
            enable_openai_api,
            enable_anthropic_api,
            enable_metrics,
            inference_only,
            listeners,
            additional_account_dirs,
            account_routing_strategy,
            account_cooldown_secs,
            session_affinity_ttl_secs,
            account_request_limits,
            experimental_compatibility,
            subscription_bridge_overrides,
            proxied_client_overrides,
            admin_key,
            allow_anonymous_admin,
            emergency_auth: crate::emergency_auth::EmergencyAuthConfig::from_env(),
            pool: crate::pool_failover::PoolPolicy::from_env(),
            mpp,
            login,
            admin_ui,
            chat_admin,
        })
        .and_then(|mut config| {
            config.management = crate::management_config::ManagementConfig::from_env()
                .map_err(ConfigError::InvalidManagementSecurity)?;
            config.model_catalog_sources =
                crate::model_catalog_sources::CatalogSourcesConfig::from_env()
                    .map_err(ConfigError::InvalidModelCatalogSources)?;
            Ok(config)
        })
    }

    /// Build a `Config` from explicit values.
    pub fn build(args: BuildArgs<'_>) -> Result<Self, ConfigError> {
        let port: u16 = args.port.parse().map_err(|_| ConfigError::InvalidPort)?;

        let listen_addr = resolve_listen_addr(args.host, port)?;

        let token_secret = args
            .token_secret
            .filter(|s| !s.is_empty())
            .ok_or(ConfigError::MissingTokenSecret)?
            .to_string();

        if matches!(
            args.upstream_provider,
            UpstreamProvider::Auto | UpstreamProvider::Gonka
        ) && matches!(args.gonka_private_key.as_deref(), Some(s) if !s.is_empty())
        {
            return Err(ConfigError::UnsupportedGonkaDirectWallet);
        }
        if args.upstream_provider == UpstreamProvider::Gonka
            && !matches!(args.gonka_api_key.as_deref(), Some(s) if !s.is_empty())
        {
            return Err(ConfigError::MissingGonkaApiKey);
        }
        if matches!(args.gonka_api_key.as_deref(), Some(s) if !s.is_empty())
            && !matches!(args.gonka_source_url.as_deref(), Some(s) if !s.is_empty())
        {
            return Err(ConfigError::MissingGonkaSourceUrl);
        }
        if args.upstream_provider == UpstreamProvider::Crater && args.crater.inbox.is_none() {
            return Err(ConfigError::MissingCraterForgeFedInbox);
        }
        if !args.account_request_limits.is_empty()
            && args.account_request_limits.len() != args.additional_account_dirs.len() + 1
        {
            return Err(ConfigError::MismatchedAccountRequestLimits);
        }
        let listeners = args
            .listeners
            .iter()
            .map(|raw| raw.parse())
            .collect::<Result<Vec<_>, _>>()
            .map_err(ConfigError::InvalidPrimaryListener)?;

        Ok(Self {
            listen_addr,
            token_secret,
            claude_code_home: args.claude_code_home.to_string(),
            upstream_base_url: args.upstream_base_url.to_string(),
            verbose: args.verbose,
            max_proxy_request_bytes: args.max_proxy_request_bytes,
            api_format: args.api_format,
            routing_mode: args.routing_mode,
            storage_policy: args.storage_policy,
            data_dir: args.data_dir,
            client_home: crate::operation_context::var_os("HOME")
                .filter(|home| !home.is_empty())
                .map_or_else(|| PathBuf::from("."), PathBuf::from),
            isolated_client_home: false,
            claude_cli_bin: args.claude_cli_bin,
            codex_cli_bin: args.codex_cli_bin,
            upstream_provider: args.upstream_provider,
            gonka_api_key: args.gonka_api_key.filter(|s| !s.is_empty()),
            gonka_source_url: args
                .gonka_source_url
                .filter(|source| !source.is_empty())
                .map(|source| source.trim_end_matches('/').to_string()),
            gonka_model: args.gonka_model,
            bridge_model: args.bridge_model.filter(|s| !s.is_empty()),
            bridge_model_policy: args
                .bridge_model_policy
                .as_deref()
                .filter(|value| !value.is_empty())
                .map_or_else(
                    || Ok(crate::bridge_selection::BridgeModelPolicy::default()),
                    crate::bridge_selection::BridgeModelPolicy::parse,
                )
                .map_err(ConfigError::InvalidBridgeModelPolicy)?,
            audit_log: args.audit_log.filter(|s| !s.is_empty()),
            crater: args.crater,
            openai_compatible: args.openai_compatible,
            activitypub_actor_base_url: args
                .activitypub_actor_base_url
                .trim_end_matches('/')
                .to_string(),
            activitypub_public_key_pem: args.activitypub_public_key_pem,
            enable_openai_api: args.enable_openai_api,
            enable_anthropic_api: args.enable_anthropic_api,
            enable_metrics: args.enable_metrics,
            inference_only: args.inference_only,
            listeners,
            additional_account_dirs: args.additional_account_dirs,
            account_routing_strategy: args.account_routing_strategy,
            account_cooldown_secs: args.account_cooldown_secs,
            session_affinity_ttl_secs: args.session_affinity_ttl_secs,
            account_request_limits: args.account_request_limits,
            experimental_compatibility: args.experimental_compatibility,
            subscription_entitlement_policy:
                crate::client_policy::SubscriptionEntitlementPolicy::parse(
                    args.subscription_bridge_overrides,
                )
                .map_err(ConfigError::InvalidSubscriptionBridgePolicy)?
                .with_proxied_clients(args.proxied_client_overrides)
                .map_err(ConfigError::InvalidProxiedClientPolicy)?,
            management: crate::management_config::ManagementConfig::default(),
            model_catalog_sources: crate::model_catalog_sources::CatalogSourcesConfig::default(),
            admin_key: args.admin_key,
            allow_anonymous_admin: args.allow_anonymous_admin,
            emergency_auth: args.emergency_auth,
            pool: args.pool,
            mpp: args.mpp,
            login: crate::login::LoginConfig {
                claude_code_home: PathBuf::from(args.claude_code_home),
                ..args.login
            },
            admin_ui: args.admin_ui,
            chat_admin: args.chat_admin,
        })
    }
}

fn resolve_listen_addr(host: &str, port: u16) -> Result<SocketAddr, ConfigError> {
    if let Ok(ip) = host.parse::<IpAddr>() {
        // The documented default remains a deliberate wildcard. A hostname,
        // however, must never widen into one: aliases are used specifically to
        // select one address on a multi-network container (issue #545).
        return Ok(SocketAddr::new(ip, port));
    }
    let address = (host, port)
        .to_socket_addrs()
        .map_err(|_| ConfigError::InvalidListenHost(host.to_string()))?
        .next()
        .ok_or_else(|| ConfigError::InvalidListenHost(host.to_string()))?;
    if address.ip().is_unspecified() {
        return Err(ConfigError::InvalidListenHost(host.to_string()));
    }
    Ok(address)
}

